create or replace function public.role_of(target_id uuid) returns text language sql stable security definer set search_path = public as $$ select role from public.profiles where id = target_id; $$; grant execute on function public.role_of(uuid) to authenticated; create or replace function public.may_assign_to_client( target_client_id uuid, target_staff_id uuid ) returns boolean language sql stable security definer set search_path = public as $$ select public.current_role() = 'operations_manager' and public.can_see_client(target_client_id) and target_staff_id <> auth.uid() and public.role_of(target_staff_id) in ('staff', 'videographer'); $$; grant execute on function public.may_assign_to_client(uuid, uuid) to authenticated; drop policy if exists "client_staff: ops manager assigns workers" on client_staff; create policy "client_staff: ops manager assigns workers" on client_staff for insert with check (public.may_assign_to_client(client_id, staff_id)); drop policy if exists "client_staff: ops manager unassigns workers" on client_staff; create policy "client_staff: ops manager unassigns workers" on client_staff for delete using (public.may_assign_to_client(client_id, staff_id));
